-- Z Warriors Online (worker.js).
CREATE TABLE IF NOT EXISTS zw_rooms (code TEXT PRIMARY KEY, v INTEGER NOT NULL, disc TEXT NOT NULL, rules TEXT NOT NULL, round INTEGER NOT NULL DEFAULT 0, ip TEXT NOT NULL DEFAULT '', created INTEGER NOT NULL, touched INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS zw_players (code TEXT NOT NULL, slot INTEGER NOT NULL, key TEXT NOT NULL, name TEXT NOT NULL DEFAULT '', addrs TEXT NOT NULL DEFAULT '[]', seen TEXT NOT NULL DEFAULT '', warrior TEXT NOT NULL, rev INTEGER NOT NULL DEFAULT 1, ready INTEGER NOT NULL DEFAULT 0, touched INTEGER NOT NULL, PRIMARY KEY (code, slot));
CREATE TABLE IF NOT EXISTS zw_quick (ticket TEXT PRIMARY KEY, key TEXT NOT NULL, v INTEGER NOT NULL, disc TEXT NOT NULL, name TEXT NOT NULL DEFAULT '', addrs TEXT NOT NULL DEFAULT '[]', seen TEXT NOT NULL DEFAULT '', warrior TEXT NOT NULL, made INTEGER NOT NULL, made_ok INTEGER NOT NULL, created INTEGER NOT NULL, touched INTEGER NOT NULL, code TEXT, mkey TEXT, slot INTEGER);
CREATE INDEX IF NOT EXISTS zw_quick_wait ON zw_quick (v, disc, code, created);
CREATE TABLE IF NOT EXISTS zw_relay_days (day INTEGER PRIMARY KEY, n INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS zw_key_days (day INTEGER NOT NULL, what TEXT NOT NULL, n INTEGER NOT NULL, PRIMARY KEY (day, what));
CREATE TABLE IF NOT EXISTS zw_limits (hour INTEGER NOT NULL, what TEXT NOT NULL, who TEXT NOT NULL, n INTEGER NOT NULL, PRIMARY KEY (hour, what, who));
